const nativeFetch=window.fetch.bind(window);
function cookieValue(name){const prefix=name+'=';for(const part of document.cookie.split(';')){const v=part.trim();if(v.startsWith(prefix))return decodeURIComponent(v.slice(prefix.length))}return ''}
window.fetch=(input,init={})=>{const method=String(init.method||'GET').toUpperCase();if(['POST','PUT','PATCH','DELETE'].includes(method)){const csrf=cookieValue('amf_csrf');if(csrf)init={...init,headers:{...(init.headers||{}),'X-AMF-CSRF':csrf}}}return nativeFetch(input,init)};
let view='hub', dash=null, projects=[], healthInfo=null, approvalsCache=[], workflowsCache=[], configMapCache=null, providersCache=[];
let miState={tab:'overview',page:1,pageSize:25,q:'',priceClass:'',capability:'',evaluation:'',provider:'',sort:'name',direction:'asc'};
