const costFmt=(c,k)=>k==='UNKNOWN'||c===null||c===undefined?'UNKNOWN':k==='FREE'?'FREE (0)':String(c);
/* Slice 10 timezone remediation (presentation only). Canonical UTC stays
   untouched in storage/API/audit/raw views. Owner-facing timestamps render
   in the browser/device local timezone via device-default formatting: no
   hardcoded zones, no manual offsets. Missing/invalid input renders '—'. */
function localTime(v){if(v===null||v===undefined)return '—';const s=String(v).trim();if(!s)return '—';const t=Date.parse(s);if(!Number.isFinite(t))return '—';try{return new Date(t).toLocaleString()}catch(e){return '—'}}
let renderEpoch=0;
