let authState=null;
async function refreshAuth(){try{authState=await jget('/api/auth/session')}catch(e){authState={signed_in:false,auth_configured:false}}}
function authChip(){if(!authState)return '<span class="badge">sign-in unknown</span>';if(!authState.auth_configured)return '<span class="badge">Owner access not configured</span>';return authState.signed_in?`<span class="badge" style="border-color:#4fd1a5;color:#4fd1a5" title="Session expires ${esc(localTime(authState.session_expires_at))}">signed in</span> <button onclick="authLogout()">Sign out</button>`:'<span class="badge">signed out · inspection only</span> <button class="primary" onclick="setView(\'login\')">Sign in</button>'}
window.authLogout=async ()=>{try{await fetch('/api/auth/logout',{method:'POST'})}catch(e){}authState=null;view='hub';render()};
function shell(content,title,sub='Morroway · operating view'){renderEpoch++;app.innerHTML=`<div class="shell"><aside class="side"><div class="brand">AMF <span>CONTROL</span></div><div class="project"><b>Morroway</b><small>PLATFORM_VALIDATION_MODE · reference project</small></div><nav>${nav.map(([id,label])=>`<button class="${view===id?'active':''}" data-view="${id}">${label}</button>`).join('')}</nav></aside><main class="main"><div class="top"><div><div class="eyebrow">${view==='hub'?'AMF / Portfolio':sub}</div><h1>${title}</h1></div><div><span id="projChip"></span> <span id="authChip">${authChip()}</span> <button onclick="setView('hub')">Switch project</button></div></div>${content}</main></div>`;document.querySelectorAll('[data-view]').forEach(x=>x.onclick=()=>setView(x.dataset.view));refreshAuth().then(()=>{const el=document.querySelector('#authChip');if(el)el.innerHTML=authChip()});refreshProjects().then(()=>{const el=document.querySelector('#projChip');if(el)el.innerHTML=projChip()});}
let projectsReady=null;
async function refreshProjects(){if(!projectsReady){projectsReady=(async()=>{try{const p=await jget('/api/runtime/projects');projects=p.projects||[]}catch(e){}})()}await projectsReady}
function projChip(){if(!projects.length)return '<span class="badge">project…</span>';const cur=projects.find(p=>p.projectId===PROJ);const label=cur?(cur.displayName||cur.projectId):PROJ;return `<span class="badge">project: ${esc(label)}</span> <select id="projSel" onchange="openProject(this.value)">${projects.map(p=>`<option value="${esc(p.projectId)}"${p.projectId===PROJ?' selected':''}>${esc(p.displayName||p.projectId)}</option>`).join('')}</select>`}
function setView(v){view=v;render()}window.setView=setView;
async function jget(u){const r=await fetch(u);const x=await r.json().catch(()=>({}));if(!r.ok)throw new Error(x.detail||x.error||('HTTP '+r.status));return x}
async function ensureDash(){if(!dash){dash=await jget('/api/projects/morroway/dashboard')}return dash}
function riskBadge(r){return r==='HIGH'?'<span class="badge" style="border-color:#ff7a7a;color:#ff9a9a">HIGH RISK</span>':r==='MEDIUM'?'<span class="badge">scoped authority</span>':'<span class="badge">gate only</span>'}
/* Slice 1 shared Owner-UX primitives: project scope, business labels, structured rendering, modal confirm, inline errors. */
const QPARAMS=new URLSearchParams(location.search);
const PROJ=(QPARAMS.get('project')||'morroway').trim()||'morroway';
const humanType=t=>({'STRATEGY':'Strategy','BRAND':'Brand','CONTENT_SYSTEM':'Content system','OBJECTIVES':'Objectives','PRINCIPLES':'Principles','CONSTRAINTS':'Constraints','EXPERIMENT':'Experiment','DECISION':'Decision','LEARNING_MEMORY':'Learning memory'}[t]||String(t));
const humanKey=(t,k)=>k==='primary'?('Primary '+humanType(t).toLowerCase()):String(k);
function renderStructured(v,depth){if(depth===undefined)depth=0;if(v===null||v===undefined)return '<span class="sub">—</span>';if(Array.isArray(v)){if(!v.length)return '<span class="sub">(empty list)</span>';return '<ul style="margin:4px 0;padding-left:18px">'+v.map(x=>'<li>'+renderStructured(x,depth+1)+'</li>').join('')+'</ul>'}if(typeof v==='object'){const ks=Object.keys(v);if(!ks.length)return '<span class="sub">(empty)</span>';return '<dl style="margin:4px 0">'+ks.map(k=>'<dt style="font-weight:700">'+esc(labelize(k))+'</dt><dd style="margin:0 0 6px 12px">'+renderStructured(v[k],depth+1)+'</dd>').join('')+'</dl>'}return '<span>'+esc(String(v))+'</span>'}
function labelize(k){return String(k).replace(/([a-z0-9])([A-Z])/g,'$1 $2').replace(/[_-]+/g,' ').replace(/\b\w/g,c=>c.toUpperCase())}
function fieldErr(id,msg){const el=document.querySelector(id);if(el)el.innerHTML=msg?`<div class="notice">${esc(msg)}</div>`:''}
/* Program 5 live Owner-action UX. Server auth remains authoritative; these
   helpers prevent signed-out controls from looking actionable and make every
   action result visible instead of leaving it in the network console. */
const pendingOwnerActions=new Set(),ownerActionMessages=new Map();
function ownerSignedIn(){return Boolean(authState&&authState.signed_in)}
function ownerActionAttrs(key){return ownerSignedIn()?`data-owner-action="${esc(key)}"`:`data-owner-action="${esc(key)}" disabled title="Sign in required"`}
function ownerActionMessage(key){const value=ownerActionMessages.get(key);return value?`<div class="notice">${esc(value)}</div>`:''}
function ownerErrorCode(status,payload={}){const raw=String(payload.code||payload.error||payload.detail||'').toUpperCase();if(status===401)return 'SIGN_IN_REQUIRED';if(status===403)return raw.includes('CSRF')?'CSRF_INVALID':'PROJECT_ACCESS_DENIED';if(status===404)return 'CREDENTIAL_NOT_FOUND';for(const code of ['PROVIDER_ERROR','EXPIRED','REVOKED','INSUFFICIENT_SCOPE','CHANNEL_IDENTITY_MISMATCH','AUTH_REQUIRED'])if(raw.includes(code))return code;return raw||`HTTP_${status||'ERROR'}`}
async function ownerActionRequest({key,output,loading,request,success,refresh}){
  if(!ownerSignedIn()){const message='SIGN_IN_REQUIRED — sign in as Owner to use this control.';ownerActionMessages.set(key,message);fieldErr(output,message);return {ok:false,error:'SIGN_IN_REQUIRED'}}
  if(pendingOwnerActions.has(key)){fieldErr(output,'ACTION_ALREADY_PENDING — duplicate click blocked.');return {ok:false,error:'ACTION_ALREADY_PENDING'}}
  pendingOwnerActions.add(key);document.querySelectorAll(`[data-owner-action="${CSS.escape(key)}"]`).forEach(button=>button.disabled=true);fieldErr(output,loading||'Working…');
  try{const response=await request();const payload=await response.json().catch(()=>({}));if(!response.ok){const code=ownerErrorCode(response.status,payload);throw Object.assign(new Error(`${code}${payload.detail||payload.error?` — ${payload.detail||payload.error}`:''}`),{code})}const message=success(payload);ownerActionMessages.set(key,message);fieldErr(output,message);if(refresh)await refresh(payload);return {ok:true,payload}}
  catch(error){const message=error&&error.message?error.message:'PROVIDER_ERROR — action failed.';ownerActionMessages.set(key,message);fieldErr(output,message);return {ok:false,error:error&&error.code||'PROVIDER_ERROR'}}
  finally{pendingOwnerActions.delete(key);document.querySelectorAll(`[data-owner-action="${CSS.escape(key)}"]`).forEach(button=>button.disabled=!ownerSignedIn())}
}
let modalSeq=0;
function confirmModal(o){const wrap=document.createElement('div');wrap.className='amf-modal';wrap.id='amfModal-'+(++modalSeq);wrap.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.6);display:flex;align-items:center;justify-content:center;z-index:50';wrap.innerHTML=`<div class="section" style="max-width:560px;width:92%"><h2>${esc(o.title)}</h2><div>${o.body}</div><div class="formrow" style="margin-top:12px"><button onclick="this.closest('.amf-modal').remove()">Cancel</button> <button class="primary amfConfirm">${esc(o.confirmLabel||'Confirm')}</button></div></div>`;document.body.appendChild(wrap);const close=()=>{if(wrap.isConnected)wrap.remove()};wrap.querySelector('.amfConfirm').onclick=()=>{o.onConfirm(close)}}
/* Slice 8 — Hub + Dashboard action orientation (presentation only).
   Decision Center remains the sole Owner-actionability truth: dashboards
   display needsDecision counts/items, never derive tasks. No synthetic
   state; unavailable data renders as honest empty/unknown states. */
/* Slice 8 domain remediation — positive project membership replaced the
   earlier namespace-blacklist filter: the Hub renders registered business
   projects only (server-side registry), so no client-side fixture guessing
   remains. */
function hubStatusChip(s){const label=String(s||"").replace(/[_-]+/g," ").replace(/\b\w/g,c=>c.toUpperCase())||"—";return s==='completed'?'<span class="badge" style="border-color:#4fd1a5;color:#4fd1a5">Completed</span>':s==='failed'?'<span class="badge" style="border-color:#ff7a7a;color:#ff9a9a">Did not complete</span>':s==='running'?'<span class="badge">Running</span>':s==='queued'?'<span class="badge">Queued</span>':`<span class="badge">${esc(label)}</span>`}
/* Slice 8 remediation — canonical authority display. Lifecycle vocabulary
   (NOT_GRANTED / NOT_PUBLISHED) is the accepted operational truth shared
   with Strategy/Decision surfaces; readiness YES/NO vocabulary must never
   be mixed in. UNKNOWN renders only when genuinely unavailable. */
function authLine(lc){const g=v=>v==='GRANTED'?'Granted':v==='PUBLISHED'?'Published':v==='NOT_GRANTED'?'Not granted':v==='NOT_PUBLISHED'?'Not published':'Unknown';const o=lc||{};return {production:g(o.productionApproval),publication:g(o.publicationApproval),public:g(o.publicStatus),raw:{production:o.productionApproval||null,publication:o.publicationApproval||null,public:o.publicStatus||null}}}
/* Deterministic next operational step from durable state only (no LLM).
   kind: decision (requires Owner) | monitor/inspect (informational) |
   workspace (starts permitted analysis-only governed work). Never infers
   production/publication permission. */
function dashNextStep(input){
  const o=input||{};
  if(o.needsDecisionCount===null||o.needsDecisionCount===undefined)return {kind:"inspect",title:"Verify Decision Center",detail:"Owner attention state is currently unknown — open Decision Center directly.",target:"approvals",requiresOwnerDecision:false};
  const need=Number(o.needsDecisionCount||0);
  if(Number.isFinite(need)&&need>0)return {kind:"decision",title:`${need} decision${need===1?"":"s"} need${need===1?"s":""} your review`,detail:"Decision Center is the sole source of Owner tasks.",target:"approvals",requiresOwnerDecision:true};
  if(Number(o.queueRunning||0)>0)return {kind:"monitor",title:"Work is running",detail:"Monitor progress in Content Pipeline; nothing is requested of you.",target:"pipeline",requiresOwnerDecision:false};
  const latest=o.latestWorkflow||null;
  if(latest&&(latest.status==='failed'||latest.status==='FAILED_TERMINAL'||latest.status==='BLOCKED'))return {kind:"inspect",title:"Latest run did not complete",detail:"Inspect what happened in Content Pipeline or Command Room.",target:"pipeline",requiresOwnerDecision:false};
  if(latest&&latest.workflowId)return {kind:"inspect",title:"Review the latest outputs",detail:"See what the last completed work produced in Artifacts.",target:"artifacts",requiresOwnerDecision:false};
  return {kind:"workspace",title:"Ask the team a question",detail:"Command Room analysis only — no production, publication, or strategy change.",target:"command",requiresOwnerDecision:false};
}
