  try{list=((await jget('/api/runtime/channels?project_id='+encodeURIComponent(PROJ))).channels||[])}catch(e){if(ep===renderEpoch)el.innerHTML=`<div class="notice">Channels unavailable: ${esc(e.message)}</div>`;return}
