async function miBenchmarks(el){const [d,r]=await Promise.all([jget('/api/model-intelligence/benchmark-plan'),jget('/api/model-intelligence/benchmark-runtime')]),p=d.executionPlan||{},pf=r.preflight||{};el.innerHTML=`<div class="notice"><b>BENCHMARK_STATUS = ${esc(d.status)}</b><br>Dataset ${esc(d.version)} · Runtime ${pf.readyForRuntime?'READY':'BLOCKED'} · Inference authorized: <b>${r.inferenceAuthorized?'YES':'NO'}</b> · ${d.benchmarkCalls} real calls · $${Number(d.spendUsd).toFixed(2)} spent.</div><div class="grid"><div class="card"><div class="sub">Fixtures / evaluators</div><div class="metric" style="font-size:16px">${r.fixtureCount} / ${r.evaluatorCount}</div></div>${Object.entries(p.stageCounts||{}).map(([k,v])=>`<div class="card"><div class="sub">Stage ${esc(k)} calls</div><div class="metric">${v}</div></div>`).join('')}<div class="card"><div class="sub">Worst-case token cost</div><div class="metric" style="font-size:16px">$${Number(p.totalWorstCaseTokenCost||0).toFixed(4)}</div></div><div class="card"><div class="sub">Hard cap</div><div class="metric" style="font-size:16px">$${Number(pf.checks?.hardCapUsd||.32).toFixed(2)}</div></div></div>${(pf.blockers||[]).length?`<div class="notice">Preflight blockers: ${(pf.blockers||[]).map(esc).join(' · ')}</div>`:`<div class="notice">Preflight V2 runtime checks pass. Real inference remains fail-closed until separately authorized.</div>`}<div class="split"><div><h2>Versioned task matrix</h2>${d.tasks.map(t=>`<div class="agent"><div><b>${esc(t.title)}</b><small>${esc(t.id)} · ${esc(t.role)}${t.creative?' · BLIND REVIEW':''}${t.critical?' · CONSISTENCY FINALISTS':''}</small></div></div>`).join('')}</div><div><h2>Runtime status</h2><p class="sub">Run ${esc(r.latestRun?.benchmarkRunId||'NONE')} · ${esc(r.latestRun?.status||'NO RUN')} · reserved $${Number(r.latestRun?.reservedSpendUsd||0).toFixed(4)} · calculable $${Number(r.latestRun?.calculableSpendUsd||0).toFixed(4)}</p><h2>Early stop</h2><p class="sub">${(p.earlyStopPolicy||[]).map(esc).join(' · ')}</p><h2>Unknown cost</h2><p class="sub">${(p.unknownCostComponents||[]).map(esc).join(' · ')}</p></div></div>`}
async function miBlind(el){const d=await jget('/api/model-intelligence/blind-reviews');el.innerHTML=`<div class="notice"><b>${esc(d.status)}</b> · No benchmark outputs exist yet.</div><h2>Subjective review contract</h2><p>Creative outputs are shown as <b>${esc(d.identityDisplay)}</b>. Model identity stays internal until the Owner submits an independent judgment, then may be revealed.</p><p class="sub">Roles: ${(d.roles||[]).map(esc).join(' · ')} · Owner judgment remains separate from automated dimensions.</p><div class="empty">No blind-review packets until an authorized benchmark run produces outputs.</div>`}
