async function miHistory(el){const model=miState.historyModel||'',d=await jget('/api/model-intelligence/price-history?limit=25'+(model?'&model_id='+encodeURIComponent(model):'')),rows=d.history||[];el.innerHTML=`<div class="notice">Immutable provider price evidence. No historical price is fabricated when only one snapshot exists.</div><div class="formrow"><input id="miHistoryModel" value="${esc(model)}" placeholder="Filter by exact model ID"><button onclick="miHistoryApply()">Apply</button><button onclick="miHistoryClear()">Clear</button></div><p class="sub">Showing up to 25 snapshots. Open a model detail for its complete focused history.</p><div class="mi-table-wrap"><table class="table"><thead><tr><th>Model</th><th>Evidence time</th><th>Input</th><th>Output</th><th>History</th><th>Availability</th></tr></thead><tbody>${rows.map(x=>`<tr onclick="miOpen('${encodeURIComponent(x.provider_model_id)}')" style="cursor:pointer"><td>${esc(x.canonical_name||x.provider_model_id)}</td><td>${esc(localTime(x.retrieved_at))}</td><td>${esc(miMoney(x.pricing_normalized?.prompt?.usdPerMillion,x.price_class))}</td><td>${esc(miMoney(x.pricing_normalized?.completion?.usdPerMillion,x.price_class))}</td><td>${Number(x.snapshot_count)>1?'PRICE_CHANGED':'NO_HISTORY_AVAILABLE'}</td><td>${esc(x.availability||'UNKNOWN')}</td></tr>`).join('')||'<tr><td colspan="6">NO_HISTORY_AVAILABLE</td></tr>'}</tbody></table></div>`}
