async function miOverviewV2(el){const d=await jget('/api/model-intelligence/overview'),c=d.catalog||{},p=d.shortlistPreview||{},r=d.routingSummary||{},recommended=[...(p.free||[]),...(p.paid||[]),...(p.reference||[])].slice(0,6);el.innerHTML=`<div class="grid">${[['Total Models',c.total],['Free',c.free],['Paid',c.paid],['Unknown Price',c.unknown],['Evaluated',c.evaluated],['Not Evaluated',c.not_evaluated],['Currently Routed',r.configured]].map(([k,v])=>`<div class="card"><div class="sub">${k}</div><div class="metric">${v||0}</div></div>`).join('')}<div class="card"><div class="sub">Last Catalog Refresh</div><div class="metric" style="font-size:14px">${esc(localTime(c.retrieved_at))}</div></div></div><div class="notice"><b>BENCHMARK_STATUS = NOT_EXECUTED</b> · Provider metadata is evidence, not an AMF quality judgment.</div><h2>Recommended for evaluation</h2><div class="mi-candidates">${recommended.map(miCandidate).join('')}</div><div class="split" style="margin-top:16px"><div><h2>Recent catalog changes</h2>${d.changes.note?`<div class="empty">${esc(d.changes.note)}</div>`:(d.changes.changed||[]).slice(0,5).map(x=>`<div class="agent"><div><b>${esc(x.canonical_name)}</b><small>${Number(x.price_snapshots)>1?'Price evidence changed':'Availability changed'} · ${esc(x.availability)}</small></div></div>`).join('')}</div><div><h2>Current routing snapshot</h2><p class="sub">${r.configured||0} of ${r.total||0} visible role entries resolve from current configuration.</p><button onclick="miTab('routing')">Review routing</button><h2 style="margin-top:16px">Next decision</h2><p class="sub">Inspect candidates, then separately authorize a bounded benchmark.</p></div></div>`}
async function platformHealth(){
  shell(`<section class="section"><h2>Platform health</h2><div id="he" class="sub">Loading…</div></section>`,'Costs & Health');
  try{
    const h=await jget('/api/runtime/health');const w=h.health;
    const workersOk=w.workers.liveCount===1&&!w.workers.stale;
    const queueOk=w.queue.queued===0&&w.queue.running===0;
    const workerCard=workersOk?'● Healthy':(w.workers.stale?'● Stale heartbeat':`● ${w.workers.liveCount} worker(s)`);
    const grouped=w.recentFailures&&w.recentFailures.length?Object.entries(w.recentFailures.reduce((m,f)=>{const k=String(f.error||'unknown').slice(0,80);m[k]=(m[k]||0)+1;return m},{})).map(([msg,n])=>`${esc(msg)} ×${n}`).join(' · '):'none recent';
    document.querySelector('#he').innerHTML=`<div class="grid"><div class="card"><div class="sub">Database</div><div class="metric">${esc(w.db)}</div><span class="badge">${w.db==='ok'?'● OK':'● Issue'}</span></div><div class="card"><div class="sub">Worker</div><div class="metric">${esc(workerCard)}</div><span class="badge">heartbeat ${esc(localTime((w.workers&&w.workers.latestHeartbeatAt)||null))}</span></div><div class="card"><div class="sub">Queue</div><div class="metric">q:${w.queue.queued} r:${w.queue.running} ok:${w.queue.succeeded} fail:${w.queue.failed}</div><span class="badge">${queueOk?'● Idle':'● Active'}</span></div></div>`
      +`<div class="agent"><div><b>Platform status: ${workersOk&&queueOk&&w.db==='ok'?'Healthy':'Needs attention'}</b><small>One persistent worker expected; builds ${esc((w.workers.buildIds||[]).join(', '))||'unknown'}${w.workers.stale?' — STALE heartbeat':''}</small></div><div><span class="badge">${workersOk?'● Healthy':'● Needs attention'}</span></div></div>`
      +`<div class="sub" style="margin-top:8px">Recent incidents (grouped): ${grouped}</div>`
      +`<details><summary>Advanced — live worker builds / recent failures</summary><table class="table"><thead><tr><th>Build</th><th>Status</th></tr></thead><tbody>${(w.workers.buildIds||[]).map(b=>`<tr><td>${esc(b)}</td><td>${esc(w.workers.stale?'STALE':'live')}</td></tr>`).join('')||'<tr><td colspan=2>unknown</td></tr>'}</tbody></table><table class="table" style="margin-top:8px"><thead><tr><th>Failed job</th><th>Workflow</th><th>Error</th></tr></thead><tbody>${(w.recentFailures||[]).slice(0,10).map(f=>`<tr><td>${f.jobId}</td><td>${esc(f.workflowId)}</td><td>${esc((f.error||'').slice(0,160))}</td></tr>`).join('')||'<tr><td colspan=3>none recent</td></tr>'}</tbody></table></details>`
      +(w.workers.liveCount!==1?'<p class="notice">Expected exactly one canonical persistent worker; multiple/stale rows indicate overlapping launchers — controlled restart required (owner decision).</p>':'');
  }catch(e){document.querySelector('#he').textContent='Health unavailable: '+e.message}
}
async function missionControl(){
  shell(`<section class="section"><h2>AMF Mission Control</h2><div id="mc" class="sub">Loading…</div></section>`,'Global System');
  try{
    const h=await jget('/api/runtime/health');const p=await jget('/api/runtime/providers');
    const pr=await jget('/api/runtime/projects').catch(()=>null);
    const w=h.health;const cur=healthCurrentStatus(w);
    const regProjects=(pr&&pr.projects)||[];
    const provList=(p.providers||[]);
    const provSummary=provList.length?provList.map(x=>`${x.provider}: ${x.availability} (health ${x.health})`).join(' · '):'No providers reported — unknown.';
    const provModels=provList.map(x=>esc(x.defaultModel||'no default model')).join(' · ')||'unknown';
    document.querySelector('#mc').innerHTML=`<div class="grid"><div class="card"><div class="sub">Platform status (current)</div><div class="metric" style="font-size:18px">${esc(cur.currentLabel)}</div><span class="badge">DB ${esc(w.db)} · ${cur.liveCount} live worker(s)</span></div><div class="card"><div class="sub">Database</div><div class="metric" style="font-size:18px">${esc(w.db)}</div><span class="badge">${cur.dbOk?'● OK':'● Issue'}</span></div><div class="card"><div class="sub">Workers (current)</div><div class="metric">${cur.liveCount}</div><span class="badge">${!cur.stale&&cur.liveCount>0?'● Healthy':'● Needs attention'}</span></div><div class="card"><div class="sub">Current queue</div><div class="metric">q:${cur.queued} r:${cur.running}</div><span class="badge">${(cur.queued===0&&cur.running===0)?'● Idle':'● Active'}</span><p class="sub">history: ok ${Number(w.queue.succeeded||0)} · fail ${Number(w.queue.failed||0)} (informational)</p></div></div>`
      +`<div class="grid" style="margin-top:14px"><div class="card"><div class="sub">Registered business projects</div><div class="metric">${regProjects.length}</div><span class="badge">canonical registry</span><p class="sub">${regProjects.map(x=>esc(x.displayName||x.projectId)).join(' · ')||'none registered'}</p></div><div class="card"><div class="sub">Providers / models</div><div class="metric" style="font-size:15px">${provList.length} provider(s)</div><span class="badge">configuration + availability summary</span><p class="sub">${esc(provSummary)}</p></div></div>`
      +`<p class="sub">Mission Control is a high-level operational overview. Detailed cost/health inspection lives on Costs &amp; Health. Status here is informational — Decision Center is the sole source of Owner actionability. Worker/provider availability grants no production authority.</p>`
      +`<details><summary>Advanced — technical details</summary><p class="sub">Builds: ${esc(((w.workers&&w.workers.buildIds)||[]).join(', ')||'unknown')} · heartbeat ${esc((w.workers&&w.workers.latestHeartbeatAt)||'unknown')} · registry IDs ${esc(regProjects.map(x=>x.projectId).join(', ')||'none')} · models ${esc(provModels)}</p></details>`
      +`<p class="notice">Localhost Owner model: read-only inspection stays open; every state-changing operation requires a valid Owner session. This does not make the platform suitable for public network exposure.</p>`;
  }catch(e){document.querySelector('#mc').textContent='System unavailable: '+e.message}
}
function settings(){
  shell(`<section class="section"><h2>Human Review Gates (real, audited)</h2><p class="sub">Gates require explicit owner approval before protected boundaries. Disabling allows future workflows to continue automatically when automated checks pass. Pending approvals are never auto-released.</p><div id="gateList" class="sub">Loading…</div><div class="formrow"><input id="gateRationale" placeholder="Owner rationale (required)"></div><div id="gateResult"></div></section><section class="section"><h2>Gate change history</h2><p class="sub">Times shown in your local timezone; raw UTC under Advanced.</p><div id="gateEvents" class="sub">Loading…</div></section><section class="section"><h2>Configuration policy</h2><p class="sub">Provider/model precedence: Global Default → Project Override → Agent Override. V1 exposes PROJECT + AGENT durable SET/RESET (see Agents). No secrets are ever returned. Config changes never trigger execution.</p></section>`,'Project Settings');
  loadGates();
}
function login(){
  shell(`<section class="section"><h2>Owner sign-in</h2><p>Sign in before changing settings, starting bounded work, or making decisions. You can continue inspecting projects, content, analytics, and history while signed out.</p><p class="sub"><b>Credential for this localhost deployment:</b> use the private Owner access token supplied by the person who configured AMF. It is configured as <code>AMF_OWNER_TOKEN</code> in the deployment's private environment file; AMF never displays the configured value. If you operate this installation yourself and do not have the token, set or rotate it in the repository-root <code>.env</code>, then restart the controlled runtime.</p><div class="formrow"><input id="loginToken" type="password" autocomplete="off" spellcheck="false" aria-label="Owner access token" placeholder="Owner access token"></div><div id="loginErr"></div><div class="formrow"><button class="primary" onclick="authLogin()">Sign in</button></div><p class="sub">Your token is sent only to this deployment's sign-in endpoint. The page clears it after sign-in and never saves it in browser storage. The browser receives a protected HttpOnly session cookie instead; it contains no raw Owner token. Sessions last 12 hours, survive a runtime restart when deployment secrets are unchanged, and end on sign-out, expiry, or secret rotation.</p></section>`,'Sign in','AMF / Owner');
}
window.authLogin=async ()=>{const t=(document.querySelector('#loginToken').value||'').trim();if(!t){fieldErr('#loginErr','Enter the Owner token.');return}fieldErr('#loginErr','');let ok=false,x={};try{const rr=await fetch('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:t})});ok=rr.ok;try{x=await rr.json()}catch(e){x={}}}catch(e){x={detail:String(e)}}if(!ok){fieldErr('#loginErr',x.detail||'sign-in failed');return}const tok=document.querySelector('#loginToken');if(tok)tok.value='';authState=null;view='hub';render()};
