window.createContent=async ()=>{const v=id=>(document.querySelector(id).value||'').trim(),t=v('#ctTitle'),o=v('#ctObjective'),topic=v('#ctTopic'),audience=v('#ctAudience'),seed=v('#ctSeed'),duration=Number(v('#ctDuration')),scenes=Number(v('#ctScenes')),character=v('#ctCharacter');if(!t){fieldErr('#ctErr','A working title is required.');return}if(!o||!topic||!audience){fieldErr('#ctErr','Objective, topic, and target audience are required.');return}if(character==='identity_critical'){fieldErr('#ctErr','Pilot 1 cannot use a recurring identity-critical person.');return}fieldErr('#ctErr','');const brief={topic,objective:o,targetPlatform:v('#ctPlatform'),format:v('#ctFormat'),targetAudience:audience,contentType:v('#ctType'),language:v('#ctLanguage'),targetDurationSeconds:duration,sceneTarget:scenes,researchRequirement:v('#ctResearch'),characterRequirement:character,identityCriticalHuman:false,aspectRatio:'9:16',brandProject:PROJ};let ok=false,x={};try{const rr=await fetch('/api/content',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({project_id:PROJ,title:t,objective:o,topic,channel:'youtube',format:'short',seed_artifact_id:seed||undefined,production_brief:brief})});ok=rr.ok;try{x=await rr.json()}catch(e){x={}}}catch(e){x={detail:String(e)}}if(!ok){fieldErr('#ctErr',typeof x.detail==='string'?x.detail.slice(0,300):(x.error||'creation failed'));return}document.querySelector('#ctOut').innerHTML=`<div class="notice">Production brief created — nothing started. <button class="primary" onclick="openContent('${esc(x.content.contentId)}')">Review it</button></div>`;content()};
