  el.innerHTML=rows+`<div class="formrow"><input id="subName" placeholder="Subject name (e.g. Host One)"> <input id="subDesc" placeholder="Canonical description"></div><div class="formrow"><input id="subRat" placeholder="Approval rationale (for Approve)"></div><div id="subErr"></div><div class="formrow"><button class="primary" onclick="createSubject()">Create subject draft</button></div><div class="formrow"><input id="subAttSubj" placeholder="Subject ID"> <input id="subRefArt" placeholder="Reference artifact ID"> <select id="subRefKind"><option value="front_portrait">front portrait</option><option value="three_quarter">3/4 portrait</option><option value="side_profile">side profile</option><option value="full_body">full body</option><option value="expression">expression</option><option value="wardrobe">wardrobe</option><option value="style">style</option></select> <button onclick="attachReference()">Attach reference</button></div><p class="sub">Attach references per subject with the Subject list above; bytes stay in artifacts.</p>`;
  for(const s of list){
    try{
      const refs=((await jget('/api/runtime/subject-references?project_id='+encodeURIComponent(PROJ)+'&subject_id='+encodeURIComponent(s.subjectId))).references||[]);
      const host=document.querySelector('#subRef-'+CSS.escape(s.subjectId));
      if(host)host.innerHTML=refs.length?`References: ${refs.map(r=>`${esc(r.referenceKind)} ${esc(r.artifactId)}${r.approved?' (approved)':''}`).join(' · ')}`:'No references attached yet.';
    }catch(e){}
  }
