  document.querySelector('#anContent').innerHTML=rows.map(c=>`<div class="agent"><div><b>${esc(c.title||'Untitled')}</b><small>views ${c.metrics&&typeof c.metrics.views==='number'?c.metrics.views:'—'} · engagement ${c.metrics&&typeof c.metrics.likes==='number'?(Number(c.metrics.likes||0)+Number(c.metrics.comments||0)+Number(c.metrics.shares||0)):'—'} · ${esc(c.transportProvenance||'no transport')}</small><br><small>${kpiLine(c)} · learnings ${c.learnings??0}</small></div><div>${availBadge(c.measurementState)} <button onclick="openContent('${esc(c.contentId)}')">Open</button></div></div>`).join('')||'<div class="empty">No content items.</div>';
