window.runCompare=async ()=>{const a=document.querySelector('#cmpA').value,b=document.querySelector('#cmpB').value,m=document.querySelector('#cmpM').value;const el=document.querySelector('#cmpOut');el.innerHTML='<div class="sub">Comparing…</div>';try{const r=await jget(`/api/runtime/analytics-comparisons?project_id=${encodeURIComponent(PROJ)}&a=${encodeURIComponent(a)}&b=${encodeURIComponent(b)}&metric=${encodeURIComponent(m)}`);el.innerHTML=`<div class="agent"><div><b>${esc(r.quality||'')}</b><small>${esc(r.reason||r.error||'')}${r.leader?` · leader: ${esc(r.leader)}`:''}${r.delta!==null&&r.delta!==undefined?` · delta ${esc(String(r.delta))}`:''}</small>${r.insight&&r.insight.text?`<br><small>${esc(r.insight.text)}</small>`:''}</div></div>`}catch(e){el.innerHTML=`<div class="notice">${esc(e.message)}</div>`}};
/* Program 5 canonical operations workspace.  It composes canonical Node
   authorities; the Python service is only the authenticated web proxy. */
const OWNER_OPERATION_READS=['owner-onboarding','owner-health','owner-routing','owner-next-cycle','owner-operation-matrix','owner-audit','revisions','owner-credential-health','owner-wan-supervised'];
async function ownerOperationReads(p,read=jget){return Promise.allSettled(OWNER_OPERATION_READS.map(resource=>read('/api/runtime/'+resource+'?'+p)))}
function supervisedWanSceneUiState(scene){const historical=Boolean(scene.historicalCanary||String(scene.workflowId||'').startsWith('wf-p4-canary-')),sourceReferenceSupported=scene.sourceVisualRuntimeReferenceSupported===true,eligible=Boolean(scene.eligible&&sourceReferenceSupported),reason=scene.eligibilityReason||(sourceReferenceSupported?'READY':'SOURCE_VISUAL_RUNTIME_REFERENCE_UNSUPPORTED');return{historical,sourceReferenceSupported,eligible,reason}}
