  const credentialHtml=credentialHealth?`${(credentialHealth.credentials||[]).map(c=>{const key='credential-'+c.bindingId;return `<div class="agent"><div><b>${esc(c.provider)} · ${esc(c.bindingId)}</b><small>${esc(c.state)} · ${c.fresh?'FRESH':'STALE'} · scope ${esc(c.scopeState)} · channel ${esc(c.channelIdentityState)} · verified ${esc(localTime(c.lastVerifiedAt))}</small><br><input id="cred-reason-${esc(c.bindingId)}" placeholder="Owner reason"><div id="cred-result-${esc(c.bindingId)}">${ownerActionMessage(key)}</div></div><div><button ${ownerActionAttrs(key)} onclick="ownerVerifyCredential('${esc(c.bindingId)}','VERIFY_HEALTH')">Verify Health</button> <button ${ownerActionAttrs(key)} onclick="ownerVerifyCredential('${esc(c.bindingId)}','REFRESH_AND_VERIFY')">Refresh & Verify</button>${ownerSignedIn()?'':'<small>Sign in required</small>'}</div></div>`}).join('')||'<div class="empty">No credential bindings.</div>'}`:`${failure(7,'Credential health')}<div class="notice"><b>Credential state: UNKNOWN / UNAVAILABLE</b><br>Reload this read before attempting Verify Health. No verification was executed.</div>`;
  document.querySelector('#owOn').innerHTML=`${onboardingHtml}<h3>Credential health</h3><p class="sub">AMF Control → Credentials → Verify Health. Health actions send only the opaque binding ID; secret references and token material are never displayed.</p>${credentialHtml}<p><button onclick="setView('dashboard')">Channel & credential controls</button></p>`;
  document.querySelector('#owHealth').innerHTML=health?`<p>Worker: ${health.worker&&health.worker.stale?'STALE/STOPPED':'HEALTHY'} · live ${(health.worker&&health.worker.liveCount)??0} · queue ${(health.queue&&health.queue.queued)??'?'}</p><div class="formrow"><input id="owWorkerReason" placeholder="Owner reason"><button ${ownerActionAttrs('worker')} onclick="ownerWorker('START')">Start</button><button ${ownerActionAttrs('worker')} onclick="ownerWorker('STOP')">Stop</button><button ${ownerActionAttrs('worker')} onclick="ownerWorker('RESTART')">Restart</button>${ownerSignedIn()?'':'<small>Sign in required</small>'}</div><div id="owWorkerOut">${ownerActionMessage('worker')}</div>${(health.alerts||[]).map(a=>`<div class="notice"><b>${esc(a.kind)} · ${esc(a.callKind||'unknown call kind')}</b><br>${esc(a.phase||a.scope||'unknown scope')} · used ${esc(a.used??'UNKNOWN')}/${esc(a.limit??'UNKNOWN')} · ${esc(a.classification||'CURRENT')} · ${a.blocksCurrentOwnerJourney?'blocks current journey':'does not block this zero-spend Owner journey'}<br>${esc(a.action)}</div>`).join('')||'<div class="empty">No derived blockers.</div>'}<div class="notice"><b>WAN MODE: TEMPORARY SUPERVISED</b><br>Legacy endpoint ${esc((health.wan&&health.wan.endpointId)||'ry49lc45y50ldy')} · maximum one POST per logical scene · no batch or automatic retry.<br>Persistent receipts unavailable · endpoint digest parity unproven · manual reconciliation may be required.<br>Each scene card independently reports whether all current generation gates pass. Hardened deployment remains deferred, not certified.</div>${(health.providers||[]).map(x=>`<div class="agent"><div><b>${esc(x.provider)}</b><small>${esc(x.catalogState)} · live health ${esc(x.liveHealth)} · last verified ${esc(localTime(x.lastVerifiedAt))}</small></div></div>`).join('')}`:failure(1,'Worker, provider and Wan health');
  const workerReady=Boolean(health&&health.worker&&!health.worker.stale&&health.worker.liveCount===1),wanReady=Boolean(wan&&wan.modeActive&&workerReady&&ownerSignedIn());
  document.querySelector('#owWan').innerHTML=wan?`<div class="notice"><b>TEMPORARY SUPERVISED WAN</b><br>One submission only. Automatic retry disabled. Manual reconciliation may be required.</div>${(wan.approvedScenes||[]).map(s=>{const key='wan-'+s.sceneId,active=s.activeExecution,{historical,eligible,reason}=supervisedWanSceneUiState(s),enabled=wanReady&&eligible&&!active;const preview=s.sourceVisualPreviewAvailable?`<img style="max-width:240px;max-height:160px" src="/api/artifacts/preview?artifact_id=${encodeURIComponent(s.sceneVisualArtifactId)}" alt="Source visual for ${esc(s.sceneId)}">`:`<div class="empty">Thumbnail unavailable · canonical artifact reference preserved</div>`;return `<div class="agent"><div>${historical?'<span class="badge">HISTORICAL CANARY</span> ':''}<b>${esc(s.contentTitle||s.contentId||'Untitled content')}</b><small>content ${esc(s.contentId)} · workflow ${esc(s.workflowId)}<br>scene ${esc(s.sceneId)} · state ${esc(s.sceneState||'VISUAL_COMPLETED_WAN_AUTHORIZED')}<br>visual ${esc(s.sceneVisualArtifactId)} · approval ${esc(s.visualApprovalState||'WAN_AUTHORIZATION_COMPLETED')}<br>semantic ${esc(s.visualSemanticState||'UNKNOWN')} · technical ${esc(s.visualTechnicalState||'UNKNOWN')}<br>Wan eligibility ${eligible?'ELIGIBLE':'BLOCKED'} · ${esc(reason)}<br>active execution ${active?esc(active.state):'NONE'}</small>${preview}${enabled?`<input id="wan-prompt-${esc(s.sceneId)}" placeholder="Exact motion prompt"><input id="wan-reason-${esc(s.sceneId)}" placeholder="Owner rationale"><div id="wan-result-${esc(s.sceneId)}">${ownerActionMessage(key)}</div>`:`<div class="notice">Generate is not offered because all current governance gates do not pass.</div>`}</div><div>${active?`<span class="badge">${esc(active.state)}</span>`:enabled?`<button onclick='ownerGenerateWanSingleScene(${JSON.stringify(s)})'>Generate Video</button>`:`<span class="badge">NOT GENERATABLE</span>`}</div></div>`}).join('')||'<div class="empty">No approved single scenes available.</div>'}${(wan.executions||[]).filter(x=>x.state==='MANUAL_RECONCILIATION_REQUIRED').map(x=>`<div class="notice"><b>MANUAL_RECONCILIATION_REQUIRED · ${esc(x.wanExecutionId)}</b><br>Scene ${esc(x.sceneId)} · visual ${esc(x.sourceVisualArtifactId)} · submitted ${esc(localTime(x.submissionStartedAt))} · endpoint ${esc(x.endpointId)} · job ${esc(x.providerJobId||'unknown')}<div class="formrow"><input id="wan-job-${esc(x.wanExecutionId)}" placeholder="Provider Job ID"><input id="wan-job-reason-${esc(x.wanExecutionId)}" placeholder="Owner rationale"><button ${ownerActionAttrs('wan-attach-'+x.wanExecutionId)} onclick="ownerAttachWanJob('${esc(x.wanExecutionId)}')">Attach Job ID</button></div><div id="wan-attach-result-${esc(x.wanExecutionId)}">${ownerActionMessage('wan-attach-'+x.wanExecutionId)}</div><small>Owner-downloaded MP4 uses the canonical audited import path and issues no POST.</small></div>`).join('')}`:failure(8,'Temporary supervised Wan');
  document.querySelector('#owRouting').innerHTML=routing?((routing.versions||[]).map(v=>`<div class="agent"><div><b>${esc(v.routingVersionId)}</b><small>${esc(v.profile)} · ${v.active?'ACTIVE':'history'} · ${(v.entries||[]).length} role(s)</small></div><div>${v.active?'<span class="badge">effective</span>':''}</div></div>`).join('')||'<div class="notice">NO_ACTIVE_ROUTING — branded execution fails closed.</div>'):failure(2,'Production routing');
  document.querySelector('#owBudgets').innerHTML=on?((on.budgets||[]).map(b=>`<div class="agent"><div><b>${esc(b.phase)} / ${esc(b.callKind)}</b><small>limit ${b.limit} · used ${b.used} · reserved ${b.reserved} · remaining ${b.remaining} · retries ${b.maxRetries}</small></div></div>`).join('')||'<div class="empty">No budgets.</div>'):failure(0,'Bounded budgets');
  document.querySelector('#owRecovery').innerHTML=revisions?((revisions.revisions||[]).map(r=>{const key='recovery-'+r.taskId;return `<div class="agent"><div><b>${esc(r.taskId)}</b><small>${esc(r.status)} · workflow ${esc(r.workflowId)} · revision ${esc(r.revisionVersion)}</small><br><small>Frozen writer/review lineage is reused; rewind begins at the canonical revision or review boundary.</small><br><input id="rec-${esc(r.taskId)}" placeholder="Owner rationale"><div id="rec-result-${esc(r.taskId)}">${ownerActionMessage(key)}</div></div><div><button ${ownerActionAttrs(key)} onclick="ownerRecovery('${esc(r.taskId)}','authorize')">Authorize revision</button> <button ${ownerActionAttrs(key)} onclick="ownerRecovery('${esc(r.taskId)}','resume-review')">Resume review only</button></div></div>`}).join('')||'<div class="empty">No recovery actions pending.</div>'):failure(6,'Recovery actions');
  document.querySelector('#owNext').innerHTML=next?((next.proposals||[]).map(x=>{const key='next-'+x.proposalId;return `<div class="agent"><div><b>${esc(x.summary)}</b><small>${esc(x.proposalId)} · ${esc(x.status)}</small><br><textarea id="ncr-${esc(x.proposalId)}" placeholder="Owner rationale"></textarea><div id="next-result-${esc(x.proposalId)}">${ownerActionMessage(key)}</div></div><div>${x.ownerDecision?`<span class="badge">${esc(x.ownerDecision.decision)}</span>`:['APPROVE','REJECT','DEFER','REQUEST_CHANGES'].map(d=>`<button ${ownerActionAttrs(key)} onclick="ownerDecideNext('${esc(x.proposalId)}','${d}')">${esc(labelize(d))}</button>`).join(' ')}${ownerSignedIn()?'':'<small>Sign in required</small>'}</div></div>`}).join('')||'<div class="empty">No proposals.</div>'):failure(3,'Next-cycle proposals');
