      +`<div class="card"><div class="sub">Current brand</div><div class="metric" style="font-size:15px">${esc(brHead(byType.BRAND)||'—')}</div>${byType.BRAND?statusBadge('ACTIVE'):'<span class="badge">missing</span>'}</div>`
      +`<div class="card"><div class="sub">Current content system</div><div class="metric" style="font-size:15px">${esc(csHead(byType.CONTENT_SYSTEM)||'—')}</div>${byType.CONTENT_SYSTEM?statusBadge('ACTIVE'):'<span class="badge">missing</span>'}</div>`
      +`<div class="card"><div class="sub">Operational authority</div><div class="metric" style="font-size:15px">Production ${esc(lc?(lc.productionApproval||'UNKNOWN'):'UNKNOWN')}</div>${authBadge(lc)}</div></div>`
      +`<p>Readiness: <b>${esc(h.status)}</b> <span class="sub">${esc(readyText)}</span></p>`
      +`<p class="sub">${esc(missingLines)}</p>`
