      +`<p>Owner action required: <b>${needAction===null?'Unknown':needAction}</b> <span class="sub">Decision Center only — a reviewable proposal is never an actionable Owner task by itself.</span></p>`
      +(e.conflicts&&e.conflicts.length?`<div class="notice">STRATEGIC_STATE_CONFLICT: ${esc(JSON.stringify(e.conflicts))}</div>`:'');
    document.querySelector('#stEff').innerHTML=`<p>Readiness: <b>${esc(h.status)}</b> <span class="sub">${esc(readyText)}</span></p>`+(active.map(a=>`<div class="agent"><div><b>${esc(humanType(a.entityType))} · ${esc(humanKey(a.entityType,a.entityKey))} · version ${a.version}</b><small>Activated ${esc(localTime(a.activatedAt))} · sources: ${esc((a.sourceArtifactIds||[]).join(', '))}</small></div><div>${statusBadge(a.status)} <button onclick="openReview('${esc(a.entityId)}')">Review</button></div></div>`).join('')||'<div class="empty">STRATEGY_NOT_CONFIGURED — no active strategic entities for this project.</div>')+(e.conflicts&&e.conflicts.length?`<div class="notice">STRATEGIC_STATE_CONFLICT: ${esc(JSON.stringify(e.conflicts))}</div>`:'');
    setHead('#stStrategyHead',stratDomainHead(byType.STRATEGY)||'Strategy');
